from pathlib import Path
import json,base64
R=Path(__file__).resolve().parents[1]/'molecules';data=json.loads((R/'data/catalog.json').read_text())
for d in data['compounds']:
 d['images']={k:('data:image/svg+xml;base64,'+base64.b64encode((R/v).read_bytes()).decode()) for k,v in d['assets'].items() if k.endswith('_svg')}
template='''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>中脑 DA · 小分子素材库</title><style>
:root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#353a3e;background:#fff;font-size:15px}*{box-sizing:border-box}body{margin:0}header{max-width:1440px;margin:auto;padding:44px 36px 22px;border-bottom:1px solid #e8e9e9}.eyebrow{font-size:11px;letter-spacing:2px;color:#8b9094}h1{font-size:30px;font-weight:540;letter-spacing:-.8px;margin:12px 0}p{line-height:1.7;color:#747b80}header p{margin:6px 0;max-width:950px}.toolbar{max-width:1440px;margin:auto;padding:22px 36px 8px;display:flex;gap:12px;flex-wrap:wrap}input,select,button,a.download{font:inherit;color:inherit;background:#fff;border:1px solid #d7dadd;border-radius:5px;padding:9px 12px}input{min-width:220px;flex:1}button,a.download{cursor:pointer}button:hover,a.download:hover{border-color:#81888f;background:#f7f8f8}a{color:#555e67;text-underline-offset:3px}#count{max-width:1440px;margin:auto;padding:12px 36px;color:#81888f;font-size:12px}.grid{max-width:1440px;margin:auto;padding:0 36px 40px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}.card{position:relative;width:100%;padding:0;text-align:left;border:1px solid #e1e3e5;border-radius:6px;overflow:hidden;background:white}.card img{width:100%;height:170px;object-fit:contain;display:block}.card .label{padding:12px 16px 15px;border-top:1px solid #eff0f0}.name{font-size:16px;font-weight:550}.sub{margin-top:7px;color:#82888e;font-size:12px;line-height:1.5}.tag{font-size:10px;letter-spacing:.2px;position:absolute;top:10px;left:12px;color:#969a9e}.arrow{float:right;color:#969a9e}dialog{border:1px solid #d9dde0;border-radius:8px;max-width:1100px;width:94vw;max-height:91vh;padding:0;box-shadow:0 10px 50px #0002}dialog::backdrop{background:#17212d55}.modalhead{display:flex;justify-content:space-between;align-items:center;padding:18px 25px;border-bottom:1px solid #e3e5e6}h2{margin:0;font-size:22px;font-weight:550}.modalbody{padding:20px 25px 28px}.structure{display:grid;grid-template-columns:1.1fr 1fr;gap:28px;align-items:center}.structure img{width:100%;height:285px;object-fit:contain}dl{display:grid;grid-template-columns:82px 1fr;gap:11px;font-size:13px;line-height:1.5}dt{color:#92979c}dd{margin:0;overflow-wrap:anywhere}.downloads{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.download{font-size:12px!important;text-decoration:none}.note{font-size:12px;background:#f5f6f6;padding:11px 14px;line-height:1.7;color:#6d747b}table{border-collapse:collapse;width:100%;font-size:12px;line-height:1.7}th,td{padding:12px 9px;border-bottom:1px solid #e8e9eb;text-align:left;vertical-align:top}th{color:#899097;font-weight:500}td:first-child{width:27%}.flag{color:#777e85;margin-top:5px;font-size:11px}.tablewrap{overflow:auto}.sectiontitle{font-size:14px;font-weight:550;margin:24px 0 4px}.coverage{max-width:1368px;margin:0 auto 44px;padding:20px 0;border-top:1px solid #e4e6e7;font-size:13px;line-height:1.8;color:#767e85}.coverage summary{cursor:pointer;font-weight:550;color:#4c545b}.coverage div{margin-top:12px}.empty{padding:40px;color:#879099;grid-column:1/-1}.footer{font-size:11px;color:#93999f;padding:0 36px 32px;max-width:1440px;margin:auto}@media(max-width:1050px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:740px){.grid{grid-template-columns:repeat(2,minmax(0,1fr));padding:0 18px 20px;gap:10px}header{padding:26px 18px 16px}.toolbar{padding:16px 18px 0}#count{padding:12px 18px}.structure{grid-template-columns:1fr;gap:0}.structure img{height:220px}.coverage{margin:10px 18px 30px}.modalbody{padding:10px 15px 20px}h1{font-size:25px}.card img{height:135px}.name{font-size:13px}.card .label{padding:10px}.tag{font-size:9px}}
</style></head><body><nav style="padding:18px 36px 0;font-size:13px"><a href="../index.html">参考入口</a> · <a href="../organoid-flow.html">流程图交互示例</a></nav><header><div class="eyebrow">MOLECULE ATLAS / HUMAN MIDBRAIN DA</div><h1>中脑多巴胺神经元 · 小分子素材库</h1><p>人 iPSC / hESC · 二维分化、神经球与三维中脑类器官。点击结构，查看完整图、用途和对应文献。</p><p style="font-size:12px">检索截至 2026-10-08 · 32 个条目 · 白底灰线 · 按已核查方法收录，尚不能视为全部文献的穷尽清单。</p></header>
<div class="toolbar"><input id="search" aria-label="搜索分子" placeholder="搜索名称、别名、通路或文献…"><select id="cat" aria-label="用途"><option value="">全部用途</option></select><select id="tier" aria-label="证据路线"><option value="">全部路线</option></select><select id="model" aria-label="培养模型"><option value="">2D + 3D</option><option>2D</option><option>3D</option></select><button id="reset">重置</button></div><div id="count" aria-live="polite"></div><main class="grid" id="grid"></main>
<details class="coverage"><summary>收录边界与未决项</summary><div>PubMed 宽检索返回 596 条，未逐篇完成全文筛选。本库包含经典 floor-plate、Kyoto、CTraS、历史 NSC 分化、MiCO / µMO / ALI 类器官及 NGN2 辅助路线；每条收录证据不等于该方法经过独立复现。具体方法见 data/catalog.json 的 evidence 条目。</div><div>文献中的时间均以各自 d0 为准。浓度是文献记录，不能拼成一个通用 protocol；原文疑似误植和不一致均保留标记。结构默认母体，不用于换算商品盐型、水合物的称量。</div><div>未确定产品身份的 “cAMP”、guggulsterone E/Z、SAG21k 的 mDA 特异性、部分商业培养基成分仍待确认。N2 / B27 / KSR / CEPT 是混合物；SHH、FGF8、BDNF、GDNF、Noggin 等是蛋白，不当作小分子。基础培养基全部营养组分不在本次结构库内。</div><div>仅在重编程、非人细胞、前脑/脊髓分支、药物损伤或检测中出现的化合物不自动纳入。详见参考入口中的使用范围说明。</div></details>
<div class="footer">STRUCTURES: PubChem + stated supplier corrections · DRAWING: RDKit · 2026-10-08.1</div>
<dialog id="detail"><div class="modalhead"><h2 id="title"></h2><button id="close" aria-label="关闭详情">关闭 ×</button></div><div class="modalbody" id="content"></div></dialog>
<script id="payload" type="application/json">__DATA__</script><script>
const DATA=JSON.parse(document.getElementById('payload').textContent), all=DATA.compounds, refs=Object.fromEntries(DATA.references.map(r=>[r.id,r]));
const $=id=>document.getElementById(id),esc=s=>String(s??'未核实').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
for(const [id,key] of [['cat','category'],['tier','tier']])for(const v of [...new Set(all.map(d=>d[key]))]){let o=document.createElement('option');o.value=v;o.textContent=v;$(id).append(o)}
function render(){const q=$('search').value.trim().toLowerCase(),cat=$('cat').value,tier=$('tier').value,model=$('model').value;const list=all.filter(d=>(!cat||d.category===cat)&&(!tier||d.tier===tier)&&(!model||d.models.some(x=>x.includes(model)))&&(!q||[d.name,d.aliases.join(' '),d.mechanism,d.source_ids.map(s=>refs[s].title).join(' ')].join(' ').toLowerCase().includes(q)));$('count').textContent=`显示 ${list.length} / ${all.length} 个条目 · 点击查看文献与下载`;$('grid').innerHTML=list.length?list.map(d=>`<button class="card" data-id="${d.id}" aria-label="查看 ${esc(d.name)}"><span class="tag">${esc(d.category)}</span><img src="${d.images.compact_svg}" alt="${esc(d.name)} 化学结构"><div class="label"><span class="arrow">↗</span><div class="name">${esc(d.name)}</div><div class="sub">${esc(d.tier)} · ${d.evidence.length} 条方法记录</div></div></button>`).join(''):'<p class="empty">没有匹配条目。</p>';document.querySelectorAll('.card').forEach(el=>el.onclick=()=>show(el.dataset.id))}
function show(id){const d=all.find(x=>x.id===id);$('title').textContent=d.name;$('content').innerHTML=`<div class="structure"><img src="${d.images.full_svg}" alt="${esc(d.name)} 完整结构"><div><dl><dt>用途</dt><dd>${esc(d.category)} · ${esc(d.tier)}</dd><dt>作用</dt><dd>${esc(d.mechanism)}</dd><dt>别名</dt><dd>${esc(d.aliases.join(' / ')||'—')}</dd><dt>分子式</dt><dd>${esc(d.drawing_formula)}</dd><dt>PubChem</dt><dd><a href="https://pubchem.ncbi.nlm.nih.gov/compound/${d.pubchem.CID}" target="_blank" rel="noreferrer">CID ${d.pubchem.CID} ↗</a></dd><dt>结构来源</dt><dd><a href="${d.structure_source}" target="_blank" rel="noreferrer">查看对应结构记录 ↗</a></dd></dl><div class="downloads"><a class="download" download="${d.id}-full.svg" href="${d.images.full_svg}">完整 SVG</a><a class="download" download="${d.id}-compact.svg" href="${d.images.compact_svg}">紧凑 SVG</a><a class="download" download="${d.id}-transparent.svg" href="${d.images.transparent_svg}">透明 SVG</a><button class="download" id="png">PNG 1200 × 800</button></div></div></div><div class="note">${esc(d.depiction_note)}${d.note?'<br>'+esc(d.note):''}</div><div class="sectiontitle">文献中的使用记录</div><div class="tablewrap"><table><thead><tr><th>出处 / 模型</th><th>原文浓度</th><th>时间 / 定位</th></tr></thead><tbody>${d.evidence.map(e=>{const r=refs[e.source_id];return `<tr><td><a href="${r.url}" target="_blank" rel="noreferrer">${esc(r.title)} ↗</a><div class="flag">${esc(r.model)}</div></td><td>${esc(e.reported_concentration)}</td><td>${esc(e.reported_window)}<div class="flag">${esc(e.locator)}</div>${e.flag?'<div class="flag">△ '+esc(e.flag)+'</div>':''}</td></tr>`}).join('')}</tbody></table></div>`;$('png').onclick=()=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas');c.width=1200;c.height=800;c.getContext('2d').drawImage(im,0,0);c.toBlob(b=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=d.id+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)},'image/png')};im.src=d.images.full_svg};$('detail').showModal()}
for(const id of ['search','cat','tier','model'])$(id).addEventListener('input',render);$('reset').onclick=()=>{for(const id of ['search','cat','tier','model'])$(id).value='';render()};$('close').onclick=()=>$('detail').close();$('detail').onclick=e=>{if(e.target===$('detail')){const r=$('detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('detail').close()}};render();
</script></body></html>'''
(R/'index.html').write_text(template.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</','<\\/')))
print('gallery bytes',(R/'index.html').stat().st_size)
